// wq#486 — Notepad architecture. Fixes the root cause verified by the
// orchestrator: agent.ts capped the notepad at 1500 chars with slice(-1500)
// (truncating from the FRONT, so notes silently fell off) while live_agent
// spliced corridor guidance INSIDE that same capped string (so the cap chopped
// guidance markers mid-section and the brain copied corrupted fragments back
// into its own notes).
//
// The fix is structural:
//   GUIDANCE  — harness->brain channel (corridor pack, stage guidance,
//               step-budget warnings). Regenerated by the harness, rendered as
//               its own prompt block, NEVER subject to note caps, NEVER
//               persisted (it is derived state).
//   NOTES     — the brain's own memory. Three regions:
//               pinned  : "PIN:"-prefixed facts; never auto-evicted; budget
//                         1500 chars — pins over budget are REJECTED loudly,
//                         never silently dropped.
//               summary : one line that accumulates a deterministic digest of
//                         evicted notes (no LLM call), so old notes degrade
//                         into a trace instead of vanishing.
//               rolling : normal notes; oldest are digested into summary when
//                         the 4500-char budget overflows.
//               Total notes ceiling: 6000 chars (~1500 tokens).
//   PERSIST   — every mutation writes through to runtime/notepad.txt (JSON);
//               bind() on boot restores it. Checkpoint sidecars carry a copy.
//               Forgetting-on-restart dies here.
import { readFileSync, writeFileSync, renameSync, mkdirSync, existsSync } from "fs";
import { dirname } from "path";

export const PIN_BUDGET = 1500;
export const ROLLING_BUDGET = 4500;
export const SUMMARY_BUDGET = 700;
export const DIGEST_CHARS = 48;   // per evicted line kept in the summary

export interface NotepadState { v: 1; pinned: string[]; summary: string; rolling: string[] }

/** wq#488 seam: a sanitizer may wrap every brain write. Return {ok:true,clean}
 *  to accept (clean replaces raw), or {ok:false,reason} to reject — note()/pin()
 *  hand the reason back to the brain as the tool result. Default = undefined =
 *  no-op passthrough (wq#486 ships this; wq#488 sets it after bind()). */
export type NotepadSanitizer = (raw: string) => { ok: boolean; clean?: string; reason?: string };

export class Notepad {
  pinned: string[] = [];
  summary = "";
  rolling: string[] = [];
  evictions = 0;
  restoredChars = 0;
  sanitizer?: NotepadSanitizer;   // wq#488 hook; unset = passthrough
  private guidance = new Map<string, string>();
  private path: string | null = null;

  /** Enable persistence: restore from `path` if present, write-through after. */
  bind(path: string): void {
    this.path = path;
    try {
      if (existsSync(path)) {
        const j = JSON.parse(readFileSync(path, "utf8")) as NotepadState;
        if (Array.isArray(j.pinned)) this.pinned = j.pinned.map(String);
        if (typeof j.summary === "string") this.summary = j.summary;
        if (Array.isArray(j.rolling)) this.rolling = j.rolling.map(String);
        this.restoredChars = this.notesChars();
      } else {
        mkdirSync(dirname(path), { recursive: true });
      }
    } catch { /* unreadable file = start fresh; never crash the agent on this */ }
  }

  /** The brain's note() tool lands here. "PIN:" prefix routes to the pinned
   *  region. Returns the one-line result the tool reports back. */
  note(text: string): string {
    let t = String(text ?? "").trim();
    if (!t) return "note: empty, ignored";
    if (this.sanitizer) {                          // wq#488 seam
      const s = this.sanitizer(t);
      if (!s.ok) return s.reason ?? "note rejected";
      t = (s.clean ?? t).trim();
      if (!t) return "note: empty after sanitize, ignored";
    }
    const m = t.match(/^PIN:\s*(.*)$/i);
    if (m) return this.pinRaw(m[1]);               // already sanitized above
    this.rolling.push(t.slice(0, 400));            // one note can't flood the pad
    const evicted = this.compact();
    this.save();
    return evicted ? `note saved (${evicted} old note(s) folded into summary)` : "note saved";
  }

  /** Pins are never auto-evicted; over budget they are REJECTED, not dropped.
   *  Public pin() applies the sanitizer; pinRaw() is the post-sanitize core. */
  pin(text: string): string {
    let t = String(text ?? "").trim();
    if (this.sanitizer) {
      const s = this.sanitizer(t);
      if (!s.ok) return s.reason ?? "pin rejected";
      t = (s.clean ?? t).trim();
    }
    return this.pinRaw(t);
  }

  private pinRaw(text: string): string {
    const t = String(text ?? "").trim().slice(0, 300);
    if (!t) return "pin: empty, ignored";
    const would = this.pinned.join("\n").length + t.length + 1;
    if (would > PIN_BUDGET)
      return `pin REJECTED: pinned region full (${this.pinned.join("\n").length}/${PIN_BUDGET} chars) - unpin nothing, pins are permanent; use a normal note`;
    this.pinned.push(t);
    this.save();
    return "PINNED (permanent)";
  }

  /** Deterministic eviction: fold OLDEST rolling lines into the summary line
   *  until under budget. No LLM call, no information cliff — each evicted
   *  line leaves a DIGEST_CHARS trace; the summary itself keeps its NEWEST
   *  tail when it overflows (oldest history fades first, twice removed). */
  private compact(): number {
    let n = 0;
    while (this.rolling.join("\n").length > ROLLING_BUDGET && this.rolling.length > 1) {
      const old = this.rolling.shift()!;
      const digest = old.slice(0, DIGEST_CHARS).replace(/\s+/g, " ");
      this.summary = this.summary ? `${this.summary} | ${digest}` : digest;
      n++; this.evictions++;
    }
    if (this.summary.length > SUMMARY_BUDGET)
      this.summary = "…" + this.summary.slice(-(SUMMARY_BUDGET - 1));
    return n;
  }

  /** Harness->brain guidance channel. Keyed sections; regenerated, not
   *  persisted, never counted against note budgets. */
  setGuidance(key: string, text: string): void {
    const t = String(text ?? "").trim();
    if (t) this.guidance.set(key, t); else this.guidance.delete(key);
  }
  hasGuidance(key: string): boolean { return this.guidance.has(key); }

  renderGuidance(): string {
    if (!this.guidance.size) return "";
    return [...this.guidance.entries()].map(([k, v]) => `-- ${k} --\n${v}`).join("\n");
  }

  renderNotes(): string {
    const parts: string[] = [];
    if (this.pinned.length) parts.push("PINNED:\n" + this.pinned.map(p => "* " + p).join("\n"));
    if (this.summary) parts.push("OLDER (compacted): " + this.summary);
    if (this.rolling.length) parts.push(this.rolling.join("\n"));
    return parts.join("\n");
  }

  notesChars(): number { return this.renderNotes().length; }

  toJSON(): NotepadState { return { v: 1, pinned: [...this.pinned], summary: this.summary, rolling: [...this.rolling] }; }

  /** Write-through (atomic rename, same pattern as retry_ledger). Failures
   *  are swallowed: persistence must never take the agent down. */
  save(): void {
    if (!this.path) return;
    try {
      writeFileSync(this.path + ".tmp", JSON.stringify(this.toJSON()));
      renameSync(this.path + ".tmp", this.path);
    } catch {}
  }
}
